import { create_presence_qrs } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    qrCreation: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      sourceName: ""
    };
  },
  methods: {
    close_dialog() {
      this.$refs.form.reset();
      this.$refs.form.resetValidation();
      this.$emit("clicked", 0);
    },
    async locationQrCreation() {
      const {
        valid
      } = await this.$refs.form?.validate?.();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(create_presence_qrs, {
            input: {
              location_id: this.rowInfo.location_id,
              qr_name: this.sourceName
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.create_presence_qrs);
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    }
  }
};
